// Logo files offered on /brand/. All are generated by scripts/brand.mjs; test/pages-brand.test.mjs
// checks that every file exists and that the dimensions below match it.

export interface BrandFile {
	/** Path under public/. */
	href: string;
	format: 'SVG' | 'PNG' | 'ICO';
	/** Pixel size for raster files, viewBox size for SVG. */
	width: number;
	height: number;
}

export interface BrandAsset {
	id: string;
	name: string;
	use: string;
	/** Background the preview sits on. */
	ground: 'paper' | 'blueprint';
	preview: BrandFile;
	files: BrandFile[];
}

const svg = (href: string, width = 32, height = 32): BrandFile => ({ href, format: 'SVG', width, height });
const png = (href: string, size: number): BrandFile => ({ href, format: 'PNG', width: size, height: size });

